let _globalLandGrid = null;
function getGlobalLandGrid() {
  if (_globalLandGrid) return _globalLandGrid;
  const grid = new Uint8Array(LAND_MASK_W * LAND_MASK_H);
  const lut = new Uint8Array(128);
  const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
  for (let i = 0; i < 64; i++) lut[chars.charCodeAt(i)] = i;
  let pos = 0, cur = 0, shift = 0, count = 0;
  for (let i = 0; i < LAND_MASK_RLE.length; i++) {
    const v = lut[LAND_MASK_RLE.charCodeAt(i)];
    count |= (v & 31) << shift;
    if (v >= 32) {
      shift += 5;
    } else {
      if (cur === 1) grid.fill(1, pos, pos + count);
      pos += count;
      cur = 1 - cur;
      count = 0;
      shift = 0;
    }
  }
  _globalLandGrid = grid;
  return grid;
}

function getLandFraction(lat, lon) {
  if (lat <= -85 || lat >= 85) return lat < 0 ? 1 : 0;
  const grid = getGlobalLandGrid();
  const fy = ((90 - lat) / 180) * LAND_MASK_H - 0.5;
  const fx = ((((lon + 180) % 360 + 360) % 360) / 360) * LAND_MASK_W - 0.5;
  const r0 = Math.max(0, Math.min(LAND_MASK_H - 1, Math.floor(fy)));
  const r1 = Math.max(0, Math.min(LAND_MASK_H - 1, r0 + 1));
  const c0 = Math.floor(fx);
  const wc0 = ((c0 % LAND_MASK_W) + LAND_MASK_W) % LAND_MASK_W;
  const wc1 = (wc0 + 1) % LAND_MASK_W;
  const ty = Math.max(0, Math.min(1, fy - r0));
  const tx = fx - c0;
  const row0 = r0 * LAND_MASK_W;
  const row1 = r1 * LAND_MASK_W;
  return (1 - ty) * ((1 - tx) * grid[row0 + wc0] + tx * grid[row0 + wc1]) +
         ty * ((1 - tx) * grid[row1 + wc0] + tx * grid[row1 + wc1]);
}

function isLandApprox(lat, lon) {
  return getLandFraction(lat, lon) >= 0.5;
}

// 24 isotropic radial samples (3 rings x 8 directions) using continuous bilinear getLandFraction
// Eliminates all axis-aligned square/stair-step coastal halos
const SHELF_RINGS = [
  { r: 0.45, w: 0.52 },
  { r: 1.05, w: 0.32 },
  { r: 2.00, w: 0.16 }
];
const SHELF_DIRS = [];
for (let a = 0; a < 8; a++) {
  const ang = (a * Math.PI) / 4;
  SHELF_DIRS.push([Math.sin(ang), Math.cos(ang)]);
}

function getCoastalShelfFactor(lat, lon) {
  let sum = 0;
  let wSum = 0;
  for (let ri = 0; ri < SHELF_RINGS.length; ri++) {
    const ring = SHELF_RINGS[ri];
    for (let di = 0; di < 8; di++) {
      const dir = SHELF_DIRS[di];
      const sLat = Math.max(-84.5, Math.min(84.5, lat + ring.r * dir[0]));
      const sLon = lon + ring.r * dir[1];
      sum += getLandFraction(sLat, sLon) * ring.w;
      wSum += ring.w;
    }
  }
  // Normalize so shelf factor peaks smoothly ~1.0 right along coastlines and fades gently into open ocean
  return Math.min(1.0, (sum / wSum) * 2.1);
}

function wrapLonDelta(lon, centerLon) {
  let d = ((lon - centerLon + 180) % 360 + 360) % 360 - 180;
  return d;
}

function gauss2d(lat, lon, cLat, cLon, sLat, sLon) {
  const dLat = (lat - cLat) / sLat;
  const dLon = wrapLonDelta(lon, cLon) / sLon;
  const r2 = dLat * dLat + dLon * dLon;
  return r2 > 18 ? 0 : Math.exp(-r2);
}

function organicEddy(lat, lon, seed = 0) {
  // Strictly integer longitude frequencies guarantee 100% seamless wrap at +-180 deg
  const x = (lon * Math.PI) / 180;
  const y = (lat * Math.PI) / 180;
  const wx = x + 0.22 * Math.sin(y * 6.0 + seed) * Math.cos(x * 4.0 - seed * 0.5);
  const wy = y + 0.22 * Math.cos(x * 5.0 - seed * 0.7) * Math.sin(y * 7.0 + seed);
  const n1 = Math.sin(wx * 4.0 + seed) * Math.cos(wy * 5.0 - seed * 0.4);
  const n2 = 0.55 * Math.sin(wx * 9.0 + 1.4 - seed * 0.8) * Math.sin(wy * 11.0 + 0.8);
  const n3 = 0.30 * Math.cos(wx * 16.0 - 0.9 + seed * 1.1) * Math.sin(wy * 17.0 + 1.9);
  return (n1 + n2 + n3) / 1.85;
}

function createCrcTable() {
  const table = new Uint32Array(256);
  for (let i = 0; i < 256; i++) {
    let c = i;
    for (let k = 0; k < 8; k++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
    table[i] = c;
  }
  return table;
}
const CRC_TABLE = createCrcTable();

function crc32(buf, offset, length) {
  let c = 0xFFFFFFFF;
  for (let i = offset; i < offset + length; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xFF] ^ (c >>> 8);
  return (c ^ 0xFFFFFFFF) >>> 0;
}

function adler32(buf, offset, length) {
  let a = 1, b = 0;
  for (let i = offset; i < offset + length; i++) {
    a = (a + buf[i]) % 65521;
    b = (b + a) % 65521;
  }
  return ((b << 16) | a) >>> 0;
}

function wrapIdatToPng(width, height, idatPayload) {
  const idatDataLen = idatPayload.length;
  const totalLen = 8 + (12 + 13) + (12 + idatDataLen) + 12;
  const out = new Uint8Array(totalLen);
  let idx = 0;
  out.set([137, 80, 78, 71, 13, 10, 26, 10], idx); idx += 8;

  function writeChunk(typeStr, data) {
    const len = data.length;
    out[idx++] = (len >> 24) & 0xFF;
    out[idx++] = (len >> 16) & 0xFF;
    out[idx++] = (len >> 8) & 0xFF;
    out[idx++] = len & 0xFF;
    const typeOffset = idx;
    for (let i = 0; i < 4; i++) out[idx++] = typeStr.charCodeAt(i);
    out.set(data, idx); idx += len;
    const c = crc32(out, typeOffset, 4 + len);
    out[idx++] = (c >> 24) & 0xFF;
    out[idx++] = (c >> 16) & 0xFF;
    out[idx++] = (c >> 8) & 0xFF;
    out[idx++] = c & 0xFF;
  }

  const ihdr = new Uint8Array(13);
  ihdr[0] = (width >> 24) & 0xFF; ihdr[1] = (width >> 16) & 0xFF; ihdr[2] = (width >> 8) & 0xFF; ihdr[3] = width & 0xFF;
  ihdr[4] = (height >> 24) & 0xFF; ihdr[5] = (height >> 16) & 0xFF; ihdr[6] = (height >> 8) & 0xFF; ihdr[7] = height & 0xFF;
  ihdr[8] = 8; ihdr[9] = 6; ihdr[10] = 0; ihdr[11] = 0; ihdr[12] = 0;
  writeChunk("IHDR", ihdr);
  writeChunk("IDAT", idatPayload);
  writeChunk("IEND", new Uint8Array(0));
  return out.subarray(0, idx);
}

function encodeRgbaToPng(width, height, rgbaBuffer) {
  const scanlineLen = 1 + width * 4;
  const rawDataLen = scanlineLen * height;
  const rawData = new Uint8Array(rawDataLen);
  for (let y = 0; y < height; y++) {
    const rowOffset = y * scanlineLen;
    rawData[rowOffset] = 0;
    const srcOffset = y * width * 4;
    rawData.set(rgbaBuffer.subarray(srcOffset, srcOffset + width * 4), rowOffset + 1);
  }

  const adler = adler32(rawData, 0, rawDataLen);
  const maxBlock = 65535;
  const numBlocks = Math.ceil(rawDataLen / maxBlock);
  let idatDataLen = 2 + rawDataLen + numBlocks * 5 + 4;
  const idatPayload = new Uint8Array(idatDataLen);
  let p = 0;
  idatPayload[p++] = 0x78;
  idatPayload[p++] = 0x01;
  for (let b = 0; b < numBlocks; b++) {
    const start = b * maxBlock;
    const end = Math.min(start + maxBlock, rawDataLen);
    const len = end - start;
    const isLast = (b === numBlocks - 1) ? 1 : 0;
    idatPayload[p++] = isLast;
    idatPayload[p++] = len & 0xFF;
    idatPayload[p++] = (len >> 8) & 0xFF;
    const nlen = (~len) & 0xFFFF;
    idatPayload[p++] = nlen & 0xFF;
    idatPayload[p++] = (nlen >> 8) & 0xFF;
    idatPayload.set(rawData.subarray(start, end), p);
    p += len;
  }
  idatPayload[p++] = (adler >> 24) & 0xFF;
  idatPayload[p++] = (adler >> 16) & 0xFF;
  idatPayload[p++] = (adler >> 8) & 0xFF;
  idatPayload[p++] = adler & 0xFF;
  return wrapIdatToPng(width, height, idatPayload.subarray(0, p));
}

async function encodeRgbaToPngCompressed(width, height, rgbaBuffer) {
  if (typeof CompressionStream !== "function") {
    return encodeRgbaToPng(width, height, rgbaBuffer);
  }
  const scanlineLen = 1 + width * 4;
  const rawData = new Uint8Array(scanlineLen * height);
  for (let y = 0; y < height; y++) {
    const rowOffset = y * scanlineLen;
    rawData[rowOffset] = 0;
    const srcOffset = y * width * 4;
    rawData.set(rgbaBuffer.subarray(srcOffset, srcOffset + width * 4), rowOffset + 1);
  }
  const cs = new CompressionStream("deflate");
  const writer = cs.writable.getWriter();
  writer.write(rawData);
  writer.close();
  const idatPayload = new Uint8Array(await new Response(cs.readable).arrayBuffer());
  return wrapIdatToPng(width, height, idatPayload);
}

function computeGlobalSst(lat, lon) {
  const latFactor = Math.cos((lat * Math.PI) / 155);
  let sst = 29.8 * Math.pow(Math.max(0, latFactor), 1.45) - 1.2;

  // Smooth wrapped 2D Gaussian ocean basins & currents (zero rectangular seams)
  sst += 1.35 * gauss2d(lat, lon, -2, 125, 13, 30);    // Indo-Pacific Warm Pool
  sst += 4.50 * gauss2d(lat, lon, 40, -50, 15, 22);    // Gulf Stream
  sst += 3.80 * gauss2d(lat, lon, 32, 142, 10, 16);    // Kuroshio Current
  sst -= 5.20 * gauss2d(lat, lon, -22, -78, 18, 9);    // Humboldt / Peru Cold Upwelling
  sst -= 4.00 * gauss2d(lat, lon, 35, -124, 12, 9);    // California Current
  sst -= 4.80 * gauss2d(lat, lon, -25, 14, 10, 6);     // Benguela Cold Upwelling

  sst += 1.65 * organicEddy(lat, lon, 0.0);
  return Math.max(-1.8, Math.min(32.5, Math.round(sst * 100) / 100));
}

function computeGlobalChlorophyll(lat, lon, coastalFactor = -1) {
  const cf = coastalFactor >= 0 ? coastalFactor : getCoastalShelfFactor(lat, lon);
  let chl = 0.12;
  const absLat = Math.abs(lat);
  // Subpolar nutrient belts
  chl += 0.52 * Math.exp(-(((absLat - 52) / 11) ** 2));
  // Equatorial upwelling belt
  chl += 0.22 * Math.exp(-((lat / 5.5) ** 2));
  // Smooth Nusantara / Coral Triangle shelf enrichment (no hard lon box)
  chl += 0.28 * gauss2d(lat, lon, -3, 120, 8, 24);
  // Major eastern boundary & monsoon upwelling plumes
  chl += 1.45 * gauss2d(lat, lon, -18, -76, 14, 6);    // Peru / Humboldt
  chl += 1.35 * gauss2d(lat, lon, -24, 13, 10, 5);     // Benguela
  chl += 1.10 * gauss2d(lat, lon, 21, -17, 10, 5);     // Canary
  chl += 0.95 * gauss2d(lat, lon, 13, 55, 10, 8);      // Somali / Arabian Sea

  chl += cf * 0.65;
  const eddy = organicEddy(lat, lon, 2.3);
  chl = chl * (0.85 + 0.52 * eddy) + 0.11 * Math.max(0, organicEddy(lat, lon, 4.1));

  return Math.max(0.03, Math.min(5.0, Math.round(chl * 10000) / 10000));
}

function computeGlobalPotentialScore(sst, chl, lat = 0, lon = 0, coastalFactor = -1) {
  const cf = coastalFactor >= 0 ? coastalFactor : getCoastalShelfFactor(lat, lon);
  const tropOpt = Math.exp(-(((sst - 28.0) / 3.2) ** 2)) * 100;
  const tempOpt = Math.exp(-(((sst - 18.0) / 4.5) ** 2)) * 88;
  const sstScore = Math.max(22, Math.min(100, Math.max(tropOpt, tempOpt)));

  const chlNorm = Math.log10(Math.max(0.04, chl) / 0.04) / Math.log10(1.5 / 0.04);
  const chlScore = Math.max(18, Math.min(100, chlNorm * 100));

  const frontScore = 54 + 44 * organicEddy(lat, lon, 1.1);
  const raw = 0.36 * sstScore + 0.42 * chlScore + 0.22 * frontScore + cf * 15;
  return Math.max(12, Math.min(99, Math.round(raw)));
}

function resolveGlobalSeaName(lat, lon) {
  if (lon >= 95 && lon <= 142 && lat >= -11 && lat <= 8) return "Perairan Nusantara / Segitiga Terumbu Karang";
  if ((lon >= 100 && lon <= 180) || (lon >= -180 && lon <= -70)) {
    if (lat > 23.5) return "Samudra Pasifik Utara";
    if (lat < -23.5) return "Samudra Pasifik Selatan";
    return "Samudra Pasifik Tropis";
  }
  if (lon >= -70 && lon <= 20) {
    if (lat > 23.5) return "Samudra Atlantik Utara";
    if (lat < -23.5) return "Samudra Atlantik Selatan";
    return "Samudra Atlantik Tropis";
  }
  if (lon >= 20 && lon <= 100 && lat <= 30) {
    if (lat < -23.5) return "Samudra Hindia Selatan";
    return "Samudra Hindia Tropis";
  }
  if (lat < -60) return "Samudra Antarktika (Southern Ocean)";
  if (lat > 66) return "Samudra Arktik";
  return "Perairan Internasional";
}

function smoothstep(edge0, edge1, x) {
  const t = Math.max(0, Math.min(1, (x - edge0) / (edge1 - edge0)));
  return t * t * (3 - 2 * t);
}

function sstToRgba(sst) {
  let u;
  if (sst < 18.0) {
    u = Math.max(0, (sst + 2.0) / 20.0) * 0.42;
  } else if (sst < 26.0) {
    u = 0.42 + ((sst - 18.0) / 8.0) * 0.23;
  } else {
    u = 0.65 + Math.min(1, (sst - 26.0) / 5.2) * 0.35;
  }
  const a = Math.round(145 + 65 * smoothstep(0.15, 0.85, u));
  if (u < 0.25) {
    const t = u / 0.25;
    return [Math.round(13 + (106 - 13) * t), Math.round(8 + (0 - 8) * t), Math.round(135 + (168 - 135) * t), a];
  } else if (u < 0.50) {
    const t = (u - 0.25) / 0.25;
    return [Math.round(106 + (192 - 106) * t), Math.round(0 + (54 - 0) * t), Math.round(168 + (132 - 168) * t), a];
  } else if (u < 0.72) {
    const t = (u - 0.50) / 0.22;
    return [Math.round(192 + (232 - 192) * t), Math.round(54 + (108 - 54) * t), Math.round(132 + (90 - 132) * t), a];
  } else if (u < 0.88) {
    const t = (u - 0.72) / 0.16;
    return [Math.round(232 + (252 - 232) * t), Math.round(108 + (168 - 108) * t), Math.round(90 + (52 - 90) * t), a];
  } else {
    const t = (u - 0.88) / 0.12;
    return [Math.round(252 + (245 - 252) * t), Math.round(168 + (246 - 168) * t), Math.round(52 + (42 - 52) * t), a];
  }
}

function chlorophyllToRgba(chl) {
  const logVal = Math.log10(Math.max(0.03, chl) / 0.03) / Math.log10(2.2 / 0.03);
  const u = Math.max(0, Math.min(1, logVal));
  // Low-chlorophyll open ocean stays subtle & translucent; blooms glow vividly
  const a = Math.round(48 + 185 * smoothstep(0.18, 0.88, u));
  if (u < 0.28) {
    const t = u / 0.28;
    return [Math.round(56 + (52 - 56) * t), Math.round(10 + (82 - 10) * t), Math.round(88 + (139 - 88) * t), a];
  } else if (u < 0.56) {
    const t = (u - 0.28) / 0.28;
    return [Math.round(52 + (28 - 52) * t), Math.round(82 + (152 - 82) * t), Math.round(139 + (142 - 139) * t), a];
  } else if (u < 0.80) {
    const t = (u - 0.56) / 0.24;
    return [Math.round(28 + (94 - 28) * t), Math.round(152 + (206 - 152) * t), Math.round(142 + (96 - 142) * t), a];
  } else {
    const t = (u - 0.80) / 0.20;
    return [Math.round(94 + (250 - 94) * t), Math.round(206 + (232 - 206) * t), Math.round(96 + (42 - 96) * t), a];
  }
}

function potentialToRgba(pot) {
  const u = Math.max(0, Math.min(1, (pot - 22) / 68));
  // Quiet open water (<45%) stays subtle so hotspots (>=72%) pop unmistakably
  const a = Math.round(40 + 195 * smoothstep(0.12, 0.85, u));
  if (u < 0.36) {
    const t = u / 0.36;
    return [Math.round(12 + (20 - 12) * t), Math.round(85 + (178 - 85) * t), Math.round(110 + (162 - 110) * t), a];
  } else if (u < 0.68) {
    const t = (u - 0.36) / 0.32;
    return [Math.round(20 + (34 - 20) * t), Math.round(178 + (197 - 178) * t), Math.round(162 + (94 - 162) * t), a];
  } else {
    const t = (u - 0.68) / 0.32;
    return [Math.round(34 + (248 - 34) * t), Math.round(197 + (168 - 197) * t), Math.round(94 + (18 - 94) * t), a];
  }
}

