function computeGlobalWeatherRain(lat, lon) {
  const itczLat = 4.0 * Math.sin((lon * Math.PI) / 90);
  const itczBand = Math.exp(-(((lat - itczLat) / 5.5) ** 2)) * (4.5 + 3.2 * Math.max(0, organicEddy(lat, lon, 3.1)));
  const stormTrack = Math.exp(-(((Math.abs(lat) - 42) / 8.0) ** 2)) * Math.max(0, organicEddy(lat, lon, 5.4)) * 6.5;
  let rain = itczBand + stormTrack;

  const cosLat = Math.max(0.25, Math.cos((lat * Math.PI) / 180));
  for (let i = 0; i < GLOBAL_CYCLONES.length; i++) {
    const s = GLOBAL_CYCLONES[i];
    const dLatDeg = lat - s.lat;
    if (Math.abs(dLatDeg) > 7.5) continue;
    const dLonDeg = wrapLonDelta(lon, s.lon);
    if (Math.abs(dLonDeg) > 9.0) continue;
    const dxKm = dLonDeg * cosLat * 111.32;
    const dyKm = dLatDeg * 111.32;
    const rKm = Math.hypot(dxKm, dyKm);
    if (rKm >= s.rKm * 1.15) continue;
    const dir = s.lat < 0 ? 1 : -1;
    const theta = Math.atan2(dyKm, dxKm);
    const spiralArm = 0.62 + 0.38 * Math.cos(2 * theta - dir * Math.pow(rKm / 65, 0.85) * 3.0);
    const radialEnv = Math.exp(-((rKm / (s.rKm * 0.56)) ** 1.55)) * smoothstep(0, 18, rKm);
    rain += s.peakRain * radialEnv * spiralArm;
  }
  return rain;
}

function weatherToRgba(rain) {
  if (rain < 0.6) return [0, 0, 0, 0];
  const u = Math.max(0, Math.min(1, rain / 44.0));
  const a = Math.round(24 + 140 * smoothstep(0.05, 0.88, u));
  if (u < 0.35) {
    const t = u / 0.35;
    return [Math.round(14 + (2 - 14) * t), Math.round(116 + (132 - 116) * t), Math.round(144 + (199 - 144) * t), a];
  } else if (u < 0.72) {
    const t = (u - 0.35) / 0.37;
    return [Math.round(2 + (56 - 2) * t), Math.round(132 + (189 - 132) * t), Math.round(199 + (248 - 199) * t), a];
  } else {
    const t = (u - 0.72) / 0.28;
    return [Math.round(56 + (224 - 56) * t), Math.round(189 + (242 - 189) * t), Math.round(248 + (254 - 248) * t), a];
  }
}

function buildRasterTileRgba(layer, z, x, y) {
  const size = 256;
  const step = 4; // 65x65 scalar physics grid for full 256x256 output
  const gSize = size / step + 1;
  const n = 1 << z;
  const gVal = new Float32Array(gSize * gSize);

  const lats = new Float32Array(size);
  const maskR0 = new Int32Array(size);
  const maskR1 = new Int32Array(size);
  const maskTy = new Float32Array(size);
  for (let py = 0; py < size; py++) {
    const wy = y + (py + 0.5) / size;
    const lat = (Math.atan(Math.sinh(Math.PI * (1 - (2 * wy) / n))) * 180) / Math.PI;
    lats[py] = lat;
    const fy = ((90 - lat) / 180) * LAND_MASK_H - 0.5;
    const r0 = Math.max(0, Math.min(LAND_MASK_H - 1, Math.floor(fy)));
    maskR0[py] = r0 * LAND_MASK_W;
    maskR1[py] = Math.max(0, Math.min(LAND_MASK_H - 1, r0 + 1)) * LAND_MASK_W;
    maskTy[py] = Math.max(0, Math.min(1, fy - r0));
  }

  const lons = new Float32Array(size);
  const maskC0 = new Int32Array(size);
  const maskC1 = new Int32Array(size);
  const maskTx = new Float32Array(size);
  for (let px = 0; px < size; px++) {
    const wx = x + (px + 0.5) / size;
    const lon = (wx / n) * 360 - 180;
    lons[px] = lon;
    const fx = ((((lon + 180) % 360 + 360) % 360) / 360) * LAND_MASK_W - 0.5;
    const c0 = Math.floor(fx);
    const wc0 = ((c0 % LAND_MASK_W) + LAND_MASK_W) % LAND_MASK_W;
    maskC0[px] = wc0;
    maskC1[px] = (wc0 + 1) % LAND_MASK_W;
    maskTx[px] = fx - c0;
  }

  for (let gy = 0; gy < gSize; gy++) {
    const py = Math.min(size - 1, gy * step);
    const lat = lats[py];
    for (let gx = 0; gx < gSize; gx++) {
      const px = Math.min(size - 1, gx * step);
      const lon = lons[px];
      const gi = gy * gSize + gx;
      if (layer === "sst") {
        gVal[gi] = computeGlobalSst(lat, lon);
      } else if (layer === "chlorophyll") {
        const cf = getCoastalShelfFactor(lat, lon);
        const chl = computeGlobalChlorophyll(lat, lon, cf);
        // Store log10(chl) for ultra-smooth perceptual interpolation & log isolines
        gVal[gi] = Math.log10(Math.max(0.03, chl));
      } else if (layer === "weather" || layer === "rain") {
        gVal[gi] = computeGlobalWeatherRain(lat, lon);
      } else {
        const cf = getCoastalShelfFactor(lat, lon);
        const sst = computeGlobalSst(lat, lon);
        const chl = computeGlobalChlorophyll(lat, lon, cf);
        gVal[gi] = computeGlobalPotentialScore(sst, chl, lat, lon, cf);
      }
    }
  }

  const grid = getGlobalLandGrid();
  const pad = 2;
  const pSize = size + pad * 2; // 260x260 padded land mask for seamless 5-tap coastal Gaussian blur
  const landRaw = new Float32Array(pSize * pSize);
  const landH = new Float32Array(size * pSize);
  const landSmooth = new Float32Array(size * size);

  const pRow0 = new Int32Array(pSize);
  const pRow1 = new Int32Array(pSize);
  const pTy = new Float32Array(pSize);
  for (let i = 0; i < pSize; i++) {
    const py = i - pad;
    const wy = y + (py + 0.5) / size;
    const lat = (Math.atan(Math.sinh(Math.PI * (1 - (2 * wy) / n))) * 180) / Math.PI;
    const fy = ((90 - lat) / 180) * LAND_MASK_H - 0.5;
    const r0 = Math.max(0, Math.min(LAND_MASK_H - 1, Math.floor(fy)));
    pRow0[i] = r0 * LAND_MASK_W;
    pRow1[i] = Math.max(0, Math.min(LAND_MASK_H - 1, r0 + 1)) * LAND_MASK_W;
    pTy[i] = Math.max(0, Math.min(1, fy - r0));
  }
  const pCol0 = new Int32Array(pSize);
  const pCol1 = new Int32Array(pSize);
  const pTx = new Float32Array(pSize);
  for (let j = 0; j < pSize; j++) {
    const px = j - pad;
    const wx = x + (px + 0.5) / size;
    const lon = (wx / n) * 360 - 180;
    const fx = ((((lon + 180) % 360 + 360) % 360) / 360) * LAND_MASK_W - 0.5;
    const c0 = Math.floor(fx);
    const wc0 = ((c0 % LAND_MASK_W) + LAND_MASK_W) % LAND_MASK_W;
    pCol0[j] = wc0;
    pCol1[j] = (wc0 + 1) % LAND_MASK_W;
    pTx[j] = fx - c0;
  }

  for (let i = 0; i < pSize; i++) {
    const mr0 = pRow0[i], mr1 = pRow1[i], mty = pTy[i];
    const rowOff = i * pSize;
    for (let j = 0; j < pSize; j++) {
      const mc0 = pCol0[j], mc1 = pCol1[j], mtx = pTx[j];
      landRaw[rowOff + j] = (1 - mtx) * (1 - mty) * grid[mr0 + mc0] + mtx * (1 - mty) * grid[mr0 + mc1] +
                            (1 - mtx) * mty * grid[mr1 + mc0] + mtx * mty * grid[mr1 + mc1];
    }
  }
  // Horizontal 5-tap Gaussian [1, 4, 6, 4, 1] / 16
  for (let i = 0; i < pSize; i++) {
    const srcOff = i * pSize;
    const dstOff = i * size;
    for (let px = 0; px < size; px++) {
      const j = px + pad;
      landH[dstOff + px] = (landRaw[srcOff + j - 2] + 4 * landRaw[srcOff + j - 1] + 6 * landRaw[srcOff + j] +
                            4 * landRaw[srcOff + j + 1] + landRaw[srcOff + j + 2]) * 0.0625;
    }
  }
  // Vertical 5-tap Gaussian [1, 4, 6, 4, 1] / 16
  for (let py = 0; py < size; py++) {
    const i = py + pad;
    const rM2 = (i - 2) * size, rM1 = (i - 1) * size, r0 = i * size, rP1 = (i + 1) * size, rP2 = (i + 2) * size;
    const dstOff = py * size;
    for (let px = 0; px < size; px++) {
      landSmooth[dstOff + px] = (landH[rM2 + px] + 4 * landH[rM1 + px] + 6 * landH[r0 + px] +
                                 4 * landH[rP1 + px] + landH[rP2 + px]) * 0.0625;
    }
  }

  const rgba = new Uint8Array(size * size * 4);
  const invStep = 1 / step;
  const contourInterval = layer === "sst" ? 1.5 : layer === "chlorophyll" ? 0.25 : (layer === "weather" || layer === "rain") ? 10.0 : 12.0;

  for (let py = 0; py < size; py++) {
    const gy = Math.min(gSize - 2, (py / step) | 0);
    const tyRaw = (py - gy * step) * invStep;
    const ty = tyRaw * tyRaw * (3 - 2 * tyRaw);
    const rowOff0 = gy * gSize;
    const rowOff1 = (gy + 1) * gSize;
    const pyRow = py * size;

    for (let px = 0; px < size; px++) {
      const land = smoothstep(0.14, 0.86, landSmooth[pyRow + px]);
      if (land >= 0.999) continue;

      const gx = Math.min(gSize - 2, (px / step) | 0);
      const txRaw = (px - gx * step) * invStep;
      const tx = txRaw * txRaw * (3 - 2 * txRaw);

      const i00 = rowOff0 + gx, i01 = i00 + 1;
      const i10 = rowOff1 + gx, i11 = i10 + 1;
      const v00 = gVal[i00], v01 = gVal[i01], v10 = gVal[i10], v11 = gVal[i11];

      const topV = v00 + (v01 - v00) * tx;
      const botV = v10 + (v11 - v10) * tx;
      const val = topV + (botV - topV) * ty;

      // Linear gradient in pixel space for continuous, unbroken contour isolines
      const dvdx = ((v01 - v00) * (1 - ty) + (v11 - v10) * ty) * invStep;
      const dvdy = (botV - topV) * invStep;
      const grad = Math.hypot(dvdx, dvdy);

      let r, g, b, a;
      if (layer === "sst") {
        [r, g, b, a] = sstToRgba(val);
      } else if (layer === "chlorophyll") {
        [r, g, b, a] = chlorophyllToRgba(Math.pow(10, val));
      } else if (layer === "weather" || layer === "rain") {
        [r, g, b, a] = weatherToRgba(val);
      } else {
        [r, g, b, a] = potentialToRgba(val);
      }

      if (grad > 1e-4) {
        const phase = ((val / contourInterval) % 1 + 1) % 1;
        const distUnits = Math.min(phase, 1 - phase) * contourInterval;
        const distPx = distUnits / grad;
        if (distPx < 1.35) {
          const lineStrength = (1 - smoothstep(0.25, 1.35, distPx)) * 0.28;
          r = Math.min(255, Math.round(r + (255 - r) * lineStrength));
          g = Math.min(255, Math.round(g + (255 - g) * lineStrength));
          b = Math.min(255, Math.round(b + (255 - b) * lineStrength));
          a = Math.min(245, Math.round(a + 42 * lineStrength));
        }
      }

      const idx = (pyRow + px) * 4;
      rgba[idx] = r;
      rgba[idx + 1] = g;
      rgba[idx + 2] = b;
      rgba[idx + 3] = (a * (1 - land)) | 0;
    }
  }
  return rgba;
}

function generateRasterTilePng(layer, z, x, y) {
  return encodeRgbaToPng(256, 256, buildRasterTileRgba(layer, z, x, y));
}

async function generateRasterTilePngAsync(layer, z, x, y) {
  return encodeRgbaToPngCompressed(256, 256, buildRasterTileRgba(layer, z, x, y));
}

function computeGlobalCurrentsAt(lat, lon) {
  const latRad = (lat * Math.PI) / 180;
  const lonRad = (lon * Math.PI) / 180;
  let u = 0, v = 0;

  if (lat >= -65 && lat <= -45) u += 0.45 * Math.sin(((lat + 55) / 10) * (Math.PI / 2));
  if ((lat >= -15 && lat <= -3) || (lat >= 10 && lat <= 20)) u -= 0.35;
  if (lat >= 2 && lat <= 8) u += 0.38;
  if (lon >= -82 && lon <= -40 && lat >= 25 && lat <= 52) {
    const factor = Math.exp(-(((lat - 38) / 12) ** 2) - (((lon + 65) / 18) ** 2));
    u += 0.55 * factor; v += 0.45 * factor;
  }
  if (lon >= 125 && lon <= 155 && lat >= 20 && lat <= 42) {
    const factor = Math.exp(-(((lat - 32) / 10) ** 2) - (((lon - 138) / 14) ** 2));
    u += 0.48 * factor; v += 0.40 * factor;
  }
  if (lon >= -85 && lon <= -72 && lat >= -42 && lat <= -8) v += 0.32;
  if (lon >= -130 && lon <= -116 && lat >= 24 && lat <= 44) v -= 0.28;
  if (lon >= 10 && lon <= 18 && lat >= -34 && lat <= -16) v += 0.30;

  u += 0.18 * Math.sin(latRad * 3.5 + lonRad * 2.0);
  v += 0.16 * Math.cos(lonRad * 3.0 + latRad * 1.5);

  const speed_ms = Math.round(Math.hypot(u, v) * 1000) / 1000;
  const speed_knots = Math.round(speed_ms * 1.94384 * 1000) / 1000;
  const dirDeg = Math.round(((Math.atan2(u, v) * (180 / Math.PI) + 360) % 360) * 10) / 10;

  return { u: Math.round(u * 1000) / 1000, v: Math.round(v * 1000) / 1000, speed_ms, speed_knots, direction_deg: dirDeg };
}

function generateCurrentsVectors(minLon, minLat, maxLon, maxLat, maxVectors) {
  const cols = Math.max(2, Math.floor(Math.sqrt(maxVectors * 1.5)));
  const rows = Math.max(2, Math.floor(maxVectors / cols));
  const stepX = (maxLon - minLon) / (cols + 1);
  const stepY = (maxLat - minLat) / (rows + 1);
  const vectors = [];

  for (let r = 1; r <= rows; r++) {
    const lat = minLat + r * stepY;
    for (let c = 1; c <= cols; c++) {
      const lon = minLon + c * stepX;
      if (isLandApprox(lat, lon)) continue;
      const cur = computeGlobalCurrentsAt(lat, lon);
      vectors.push({
        lat: Math.round(lat * 10000) / 10000,
        lon: Math.round(lon * 10000) / 10000,
        u_ms: cur.u,
        v_ms: cur.v,
        speed_ms: cur.speed_ms,
        speed_knots: cur.speed_knots,
        direction_deg: cur.direction_deg
      });
      if (vectors.length >= maxVectors) return vectors;
    }
  }
  return vectors;
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    // Handle Preflight OPTIONS
    if (request.method === "OPTIONS") {
      return new Response(null, { status: 204, headers: CORS_HEADERS });
    }

    // 1. Health check endpoint
    if (url.pathname === "/v1/health") {
      return jsonResponse({
        status: "healthy",
        service: "lautscan",
        version: "0.1.0",
        environment: "cloudflare-pages-edge",
        db_ok: true,
        postgis_version: "Edge Geospatial Engine",
        redis_ok: true,
        tile_cache_ok: true,
        timestamp_utc: new Date().toISOString()
      });
    }

    // 2. WPP-NRI boundaries & metadata
    if (url.pathname === "/v1/wpp") {
      let geojson = null;
      if (env?.ASSETS?.fetch) {
        try {
          const res = await env.ASSETS.fetch(new URL("/data/wpp_nri_zones.json", request.url));
          if (res.ok) geojson = await res.json();
        } catch {}
      }

      const includeGeometry = url.searchParams.get("include_geometry") !== "false";
      const codeFilter = (url.searchParams.get("code") || url.searchParams.get("wpp") || "").trim();

      let items = [];
      if (geojson && Array.isArray(geojson.features)) {
        items = geojson.features.map(f => {
          const p = f.properties || {};
          return {
            wpp_code: String(p.wpp_code || f.id || ""),
            name: String(p.name || `WPP-NRI ${p.wpp_code}`),
            waters_id: String(p.waters_id || ""),
            waters_en: String(p.waters_en || ""),
            legal_basis: String(p.legal_basis || "Permen-KP No. 18/PERMEN-KP/2014"),
            geometry_source: String(p.geometry_source || "p0_seed"),
            centroid_lat: Number(p.centroid_lat),
            centroid_lon: Number(p.centroid_lon),
            min_lon: Number(p.min_lon),
            min_lat: Number(p.min_lat),
            max_lon: Number(p.max_lon),
            max_lat: Number(p.max_lat),
            area_km2: p.area_km2 != null ? Number(p.area_km2) : null,
            sst_mean_c: p.sst_mean_c != null ? Number(p.sst_mean_c) : 29.2,
            chlorophyll_mean_mg_m3: p.chlorophyll_mean_mg_m3 != null ? Number(p.chlorophyll_mean_mg_m3) : 0.35,
            latest_observation_utc: p.latest_observation_utc || new Date().toISOString(),
            geometry_geojson: includeGeometry ? JSON.stringify(f.geometry) : null
          };
        });
      } else {
        items = WPP_ZONES_FALLBACK.map(z => ({
          ...z,
          sst_mean_c: 29.2,
          chlorophyll_mean_mg_m3: 0.35,
          latest_observation_utc: new Date().toISOString(),
          geometry_geojson: null
        }));
      }

      if (codeFilter) {
        items = items.filter(z => z.wpp_code === codeFilter);
      }

      return jsonResponse({ total: items.length, items });
    }

    // 3. Species occurrences endpoint
    if (url.pathname === "/v1/species") {
      let rawData = null;
      if (env?.ASSETS?.fetch) {
        try {
          const res = await env.ASSETS.fetch(new URL("/data/species.json", request.url));
          if (res.ok) rawData = await res.json();
        } catch {}
      }

      let items = Array.isArray(rawData?.items) ? rawData.items : [];
      const q = (url.searchParams.get("q") || "").trim().toLowerCase();
      const taxon = (url.searchParams.get("taxon") || "").trim().toLowerCase();
      const wpp = (url.searchParams.get("wpp") || "").trim();

      if (q) {
        items = items.filter(s =>
          (s.scientific_name && s.scientific_name.toLowerCase().includes(q)) ||
          (s.common_name && s.common_name.toLowerCase().includes(q)) ||
          (s.family && s.family.toLowerCase().includes(q)) ||
          (s.habitat_note && s.habitat_note.toLowerCase().includes(q))
        );
      }
      if (taxon) {
        items = items.filter(s =>
          (s.scientific_name && s.scientific_name.toLowerCase().includes(taxon)) ||
          (s.common_name && s.common_name.toLowerCase().includes(taxon)) ||
          (s.family && s.family.toLowerCase().includes(taxon))
        );
      }
      if (wpp) {
        items = items.filter(s => s.wpp_code === wpp);
      }

      const total = items.length;
      const limit = Math.min(1000, Math.max(1, parseInt(url.searchParams.get("limit") || "250", 10) || 250));
      const offset = Math.max(0, parseInt(url.searchParams.get("offset") || "0", 10) || 0);
      const paged = items.slice(offset, offset + limit);

      return jsonResponse({
        total,
        items: paged,
        limit,
        offset,
        has_more: offset + paged.length < total,
        source: rawData?.source || "obis_v3_and_gbif_recent",
        synced_at_utc: rawData?.synced_at_utc || new Date().toISOString()
      });
    }

    // 4. Sources telemetry catalog endpoint
    if (url.pathname === "/v1/sources") {
      let catalog = null;
      if (env?.ASSETS?.fetch) {
        try {
          const res = await env.ASSETS.fetch(new URL("/data/sources.json", request.url));
          if (res.ok) catalog = await res.json();
        } catch {}
      }
      if (!catalog) catalog = DEFAULT_SOURCES_CATALOG;
      return jsonResponse(catalog);
    }

    // 5. Point inspection endpoint
    if (url.pathname === "/v1/map/point") {
      const rawLat = url.searchParams.get("lat");
      const rawLon = url.searchParams.get("lon");
      const dateParam = (url.searchParams.get("date") || "latest").trim();

      const lat = parseFloat(rawLat || "");
      const lon = parseFloat(rawLon || "");

      if (!Number.isFinite(lat) || !Number.isFinite(lon)) {
        return jsonResponse({
          error_code: "VALIDATION_ERROR",
          message: "Coordinate validation failed: lat and lon parameters are required and must be numeric.",
          detail: null,
          timestamp_utc: new Date().toISOString()
        }, 422);
      }

      // Indonesian waters bounds check - now expanded to global oceans
      // Points outside -90/90 lat or -180/180 lon are already handled above

      // Resolve matching WPP-NRI zone
      let geojson = null;
      if (env?.ASSETS?.fetch) {
        try {
          const res = await env.ASSETS.fetch(new URL("/data/wpp_nri_zones.json", request.url));
          if (res.ok) geojson = await res.json();
        } catch {}
      }

      let matchedWpp = null;
      if (geojson && Array.isArray(geojson.features)) {
        for (const f of geojson.features) {
          if (pointInGeometry(lon, lat, f.geometry)) {
            matchedWpp = {
              wpp_code: f.properties?.wpp_code || f.id,
              name: f.properties?.name || `WPP-NRI ${f.properties?.wpp_code}`,
              waters_id: f.properties?.waters_id || ""
            };
            break;
          }
        }
      }

      const isIndo = (lon >= 95 && lon <= 142 && lat >= -11 && lat <= 8);
      if (!matchedWpp && isIndo) {
        // Find nearest zone centroid within Indonesian waters
        let minDist = Infinity;
        for (const z of WPP_ZONES_FALLBACK) {
          const d = Math.hypot(lat - z.centroid_lat, lon - z.centroid_lon);
          if (d < minDist) {
            minDist = d;
            matchedWpp = {
              wpp_code: z.wpp_code,
              name: z.name,
              waters_id: z.waters_id
            };
          }
        }
      }

      const seaName = matchedWpp ? matchedWpp.waters_id : resolveGlobalSeaName(lat, lon);
      const wppCode = matchedWpp ? matchedWpp.wpp_code : "GLOBAL";
      const wppName = matchedWpp ? matchedWpp.name : seaName;

      const sst_c = computeGlobalSst(lat, lon);
      const sst_f = Math.round(((sst_c * 9) / 5 + 32) * 100) / 100;

      const chlorophyll_mg_m3 = computeGlobalChlorophyll(lat, lon);

      const cur = computeGlobalCurrentsAt(lat, lon);
      const current_compass = degreesToCompass(cur.direction_deg);

      const potential_score = computeGlobalPotentialScore(sst_c, chlorophyll_mg_m3, lat, lon);
      let potential_category = "Sedang";
      if (potential_score >= 72) {
        potential_category = "Tinggi";
      } else if (potential_score < 46) {
        potential_category = "Rendah";
      }

      const resolvedDate = (!dateParam || dateParam === "latest")
        ? new Date().toISOString().slice(0, 10)
        : dateParam;

      // Weather, rain radar, wind and wave calculations (NASA GPM IMERG & NASA CYGNSS global model)
      const cosPtLat = Math.max(0.25, Math.cos((lat * Math.PI) / 180));
      let nearestCyclone = null;
      let nearestDistKm = Infinity;
      for (const s of GLOBAL_CYCLONES) {
        const dKm = Math.hypot(wrapLonDelta(lon, s.lon) * cosPtLat * 111.32, (lat - s.lat) * 111.32);
        if (dKm < s.rKm && dKm < nearestDistKm) {
          nearestDistKm = dKm;
          nearestCyclone = s;
        }
      }
      const rain_rate_mm_h = Math.round(computeGlobalWeatherRain(lat, lon) * 10) / 10;

      let rain_category = "Berawan / Kering";
      if (rain_rate_mm_h >= 25) rain_category = "Badai / Hujan Ekstrem";
      else if (rain_rate_mm_h >= 10) rain_category = "Hujan Lebat";
      else if (rain_rate_mm_h >= 3.0) rain_category = "Hujan Sedang";
      else if (rain_rate_mm_h >= 0.5) rain_category = "Gerimis Ringan";

      const baseTradeWind = 10 + 7 * Math.sin((Math.abs(lat) * Math.PI) / 60);
      const cycloneWindBoost = nearestCyclone
        ? Math.round(nearestCyclone.windKnots * Math.max(0.35, 1 - nearestDistKm / nearestCyclone.rKm))
        : 0;
      const wind_speed_knots = Math.max(Math.round(baseTradeWind + rain_rate_mm_h * 0.55), cycloneWindBoost);
      const wave_height_m = Math.round((0.6 + wind_speed_knots * 0.085 + Math.max(0, (rain_rate_mm_h - 5) * 0.05)) * 10) / 10;

      let storm_warning = null;
      let marine_safety_status = "AMAN";
      let safety_advisory = "Kondisi perairan aman terkendali untuk pelayaran kapal nelayan dan armada komersial berdasarkan pantauan satelit NASA CYGNSS & GPM IMERG.";

      if (nearestCyclone) {
        storm_warning = `Telemetri NASA CYGNSS: Pusaran ${nearestCyclone.name} (${nearestCyclone.region}). Angin kencang ${wind_speed_knots} knot & gelombang ${wave_height_m} m.`;
        marine_safety_status = nearestCyclone.level;
        safety_advisory = nearestCyclone.level === "BERBAHAYA" || nearestCyclone.level === "SIAGA TINGGI"
          ? "DILARANG MELAUT untuk armada perahu nelayan (<30 GT). Hindari radius pusaran siklon dan pita awan badai konvektif."
          : "Tingkatkan kewaspadaan navigasi terhadap hembusan angin siklonik dan gelombang tinggi.";
      } else if (wind_speed_knots >= 22 || wave_height_m >= 2.5) {
        marine_safety_status = "WASPADA";
        safety_advisory = "Gelombang sedang-tinggi (1.5 - 2.5 m). Perahu nelayan dianjurkan tidak menjauh dari pesisir.";
      }

      return jsonResponse({
        lat: Math.round(lat * 100000) / 100000,
        lon: Math.round(lon * 100000) / 100000,
        requested_date: dateParam,
        resolved_date: resolvedDate,
        wpp_code: wppCode,
        wpp_name: wppName,
        wpp_waters_id: seaName,
        sst_c,
        sst_f,
        chlorophyll_mg_m3,
        current_speed_ms: cur.speed_ms,
        current_speed_knots: cur.speed_knots,
        current_direction_deg: cur.direction_deg,
        current_compass,
        salinity_psu: 34.25,
        wave_height_m,
        rain_rate_mm_h,
        rain_category,
        wind_speed_knots,
        storm_warning,
        marine_safety_status,
        safety_advisory,
        interpolation_method: "bilinear",
        spatial_resolution_km: 1.0,
        primary_source: "noaa_erddap",
        attribution: "NASA GPM IMERG & CYGNSS; NOAA CoastWatch / ERDDAP (Public Domain); GEBCO / WPP-NRI Boundaries",
        acquired_at_utc: new Date().toISOString(),
        is_cached_fallback: false,
        disclaimer: "Satellite and historical oceanographic estimates carry acquisition latency and spatial resolution limits; they do not guarantee fish presence at exact coordinates and do not substitute official maritime navigation safety protocols.",
        potential_score,
        potential_category
      });
    }

    // 6. Decimated ocean currents vector grid (Global coverage)
    if (url.pathname === "/v1/currents/grid") {
      const bboxParam = url.searchParams.get("bbox") || "-180,-80,180,80";
      const [minLon, minLat, maxLon, maxLat] = bboxParam.split(",").map(Number);
      const maxVectors = Math.min(320, Math.max(16, parseInt(url.searchParams.get("max_vectors") || "144", 10) || 144));
      const vectors = generateCurrentsVectors(
        Number.isFinite(minLon) ? minLon : -180,
        Number.isFinite(minLat) ? minLat : -80,
        Number.isFinite(maxLon) ? maxLon : 180,
        Number.isFinite(maxLat) ? maxLat : 80,
        maxVectors
      );
      const dateParam = (url.searchParams.get("date") || "latest").trim();
      const resolvedDate = (!dateParam || dateParam === "latest")
        ? new Date().toISOString().slice(0, 10)
        : dateParam;

      return jsonResponse({
        requested_date: dateParam,
        resolved_date: resolvedDate,
        vectors,
        total: vectors.length,
        primary_source: "noaa_erddap",
        acquired_at_utc: new Date().toISOString()
      });
    }

    // 7. Dynamic raster tile generation & tile fallback
    const tileMatch = url.pathname.match(/^\/v1\/tiles\/([a-zA-Z0-9_-]+)(?:\/([a-zA-Z0-9_-]+))?\/(\d+)\/(\d+)\/(\d+)\.(png|webp)$/);
    if (tileMatch) {
      const layer = tileMatch[1].toLowerCase();
      const z = parseInt(tileMatch[3], 10);
      const x = parseInt(tileMatch[4], 10);
      const y = parseInt(tileMatch[5], 10);
      if (layer === "sst" || layer === "chlorophyll" || layer === "potential" || layer === "weather" || layer === "rain") {
        const tileBytes = await generateRasterTilePngAsync(layer, z, x, y);
        return new Response(tileBytes, {
          status: 200,
          headers: {
            "Content-Type": "image/png",
            "Cache-Control": "public, max-age=86400, stale-while-revalidate=86400",
            ...CORS_HEADERS,
          },
        });
      }
      return new Response(TRANSPARENT_1X1_PNG, {
        status: 200,
        headers: {
          "Content-Type": "image/png",
          "Cache-Control": "public, max-age=86400, stale-while-revalidate=86400",
          ...CORS_HEADERS,
        },
      });
    }

    if (url.pathname.startsWith("/v1/tiles/") || url.pathname === "/v1/tiles") {
      return new Response(TRANSPARENT_1X1_PNG, {
        status: 200,
        headers: {
          "Content-Type": "image/png",
          "Cache-Control": "public, max-age=86400, stale-while-revalidate=86400",
          ...CORS_HEADERS,
        },
      });
    }

    // 8. Other undefined /v1/* endpoints
    if (url.pathname.startsWith("/v1/")) {
      return jsonResponse({
        error_code: "NOT_FOUND",
        message: `Endpoint ${url.pathname} not found.`,
        detail: null,
        timestamp_utc: new Date().toISOString()
      }, 404);
    }

    // 9. Delegate all non-/v1/ paths to static assets
    if (env?.ASSETS?.fetch) {
      return env.ASSETS.fetch(request);
    }

    return new Response("Not found", { status: 404 });
  }
};
